insert into public.quiz_questions (id, level, difficulty, skill, prompt, audio, options, answer, explanation, sort) values
  ('n5-easy-01', 'N5', 'easy', 'Vocabulary', '「いぬ」 means:', null, array['Cat','Dog','Bird','Fish']::text[], 1, 'いぬ (犬) = dog. Cat is ねこ.', 0),
  ('n5-easy-02', 'N5', 'easy', 'Vocabulary', '「みず」 means:', null, array['Water','Fire','Rice','Tea']::text[], 0, 'みず (水) = water.', 1),
  ('n5-easy-03', 'N5', 'easy', 'Kanji', 'How is 「一」 read when counting?', null, array['いち','に','さん','よん']::text[], 0, '一 = いち (one). 二 = に, 三 = さん.', 2),
  ('n5-easy-04', 'N5', 'easy', 'Kanji', '「日」 means:', null, array['Moon','Sun / day','Tree','Fire']::text[], 1, '日 = sun or day, as in 日本 (Japan) and 日曜日 (Sunday).', 3),
  ('n5-easy-05', 'N5', 'easy', 'Vocabulary', 'How do you say “Good morning” politely?', null, array['こんばんは','おはようございます','さようなら','いただきます']::text[], 1, 'おはようございます is the polite morning greeting.', 4),
  ('n5-easy-06', 'N5', 'easy', 'Grammar', 'わたし ___ がくせいです。', null, array['を','は','に','で']::text[], 1, 'は marks the topic: “As for me, I am a student.”', 5),
  ('n5-easy-07', 'N5', 'easy', 'Vocabulary', '「ありがとう」 means:', null, array['Sorry','Thank you','Hello','Goodbye']::text[], 1, 'ありがとう = thank you.', 6),
  ('n5-easy-08', 'N5', 'easy', 'Listening', 'Listen and choose the meaning.', 'さようなら', array['Good morning','Thank you','Goodbye','Excuse me']::text[], 2, 'さようなら = goodbye.', 7),
  ('n5-easy-09', 'N5', 'easy', 'Vocabulary', 'Katakana 「コーヒー」 means:', null, array['Coffee','Cookie','Copy','Coat']::text[], 0, 'コーヒー = coffee. Katakana is used for loanwords.', 8),
  ('n5-easy-10', 'N5', 'easy', 'Vocabulary', '「ななじゅう」 is which number?', null, array['17','70','7','700']::text[], 1, 'なな (7) + じゅう (10) = 70.', 9),
  ('n5-medium-01', 'N5', 'medium', 'Grammar', 'これ ___ わたしの ほんです。', null, array['は','を','へ','で']::text[], 0, 'は marks the topic: “This is my book.”', 10),
  ('n5-medium-02', 'N5', 'medium', 'Grammar', 'がっこう ___ いきます。', null, array['を','に','が','の']::text[], 1, 'に marks the destination of movement (へ also works).', 11),
  ('n5-medium-03', 'N5', 'medium', 'Grammar', 'バス ___ かいしゃへ いきます。', null, array['で','を','に','が']::text[], 0, 'で marks the means: “I go to the office by bus.”', 12),
  ('n5-medium-04', 'N5', 'medium', 'Kanji', 'How is 「山」 read in 「やまのぼり」 (mountain climbing)?', null, array['やま','かわ','さん','た']::text[], 0, '山 is read やま on its own and さん in names like ふじさん.', 13),
  ('n5-medium-05', 'N5', 'medium', 'Vocabulary', '「きのう」 means:', null, array['Today','Tomorrow','Yesterday','Every day']::text[], 2, 'きのう = yesterday, きょう = today, あした = tomorrow.', 14),
  ('n5-medium-06', 'N5', 'medium', 'Grammar', 'すし ___ すきです。', null, array['を','が','で','に']::text[], 1, 'すき (like) takes が: すしが すきです.', 15),
  ('n5-medium-07', 'N5', 'medium', 'Reading', '「わたしは まいあさ 7じに おきます。」 When does the writer get up?', null, array['6:00','7:00','8:00','7:30']::text[], 1, '7じ = 7 o''clock. おきます = get up.', 16),
  ('n5-medium-08', 'N5', 'medium', 'Kanji', '「金よう日」 is:', null, array['Monday','Wednesday','Friday','Sunday']::text[], 2, '金曜日 = Friday. 月 = Monday, 水 = Wednesday, 日 = Sunday.', 17),
  ('n5-medium-09', 'N5', 'medium', 'Listening', 'Listen and choose the meaning.', 'いくらですか', array['Where is it?','How much is it?','What time is it?','Who is it?']::text[], 1, 'いくらですか = How much is it?', 18),
  ('n5-medium-10', 'N5', 'medium', 'Grammar', 'きのう えいがを ___。', null, array['みます','みました','みません','みて']::text[], 1, 'きのう (yesterday) needs the past tense: みました.', 19),
  ('n5-hard-01', 'N5', 'hard', 'Grammar', 'つくえの うえ ___ ねこが います。', null, array['で','を','に','へ']::text[], 2, 'に marks where something exists (with います / あります).', 20),
  ('n5-hard-02', 'N5', 'hard', 'Grammar', 'あした ともだちと こうえん ___ あそびます。', null, array['に','で','を','が']::text[], 1, 'で marks where an action happens: play at the park.', 21),
  ('n5-hard-03', 'N5', 'hard', 'Grammar', 'にほんごは むずかしい ___、おもしろいです。', null, array['から','ですが','ので','と']::text[], 1, 'ですが = but: “Japanese is difficult, but interesting.”', 22),
  ('n5-hard-04', 'N5', 'hard', 'Kanji', 'How is 「先生」 read?', null, array['せんせい','がくせい','せんしゅう','さきせい']::text[], 0, '先生 = せんせい (teacher). 学生 = がくせい (student).', 23),
  ('n5-hard-05', 'N5', 'hard', 'Grammar', 'ここで しゃしんを とって ___ ですか。', null, array['もいい','はいけない','ください','ほしい']::text[], 0, '〜てもいいですか = May I …? “May I take a photo here?”', 24),
  ('n5-hard-06', 'N5', 'hard', 'Reading', '「たなかさんは 3にん きょうだいです。おにいさんと いもうとが います。」 How many siblings does Tanaka-san have?', null, array['1','2','3','4']::text[], 1, '3にんきょうだい counts Tanaka-san too: an older brother and a younger sister = 2 siblings.', 25),
  ('n5-hard-07', 'N5', 'hard', 'Vocabulary', 'The opposite of 「たかい」 (expensive) is:', null, array['やすい','ひくい','おおきい','ながい']::text[], 0, 'たかい (expensive) ↔ やすい (cheap). For height, the opposite is ひくい.', 26),
  ('n5-hard-08', 'N5', 'hard', 'Listening', 'Listen. What is the person doing?', 'すみません、えきは どこですか', array['Asking the time','Asking where the station is','Buying a ticket','Apologising for being late']::text[], 1, 'えきは どこですか = Where is the station?', 27),
  ('n5-hard-09', 'N5', 'hard', 'Grammar', 'The polite past negative of のみます is:', null, array['のみませんでした','のみました','のみません','のまない']::text[], 0, '〜ませんでした = didn''t (polite past negative).', 28),
  ('n5-hard-10', 'N5', 'hard', 'Kanji', '「来週」 means:', null, array['Last week','This week','Next week','Every week']::text[], 2, '来週 = next week. 先週 = last week, 今週 = this week.', 29),
  ('n4-easy-01', 'N4', 'easy', 'Vocabulary', '「しゅくだい」 means:', null, array['Homework','Holiday','Lunch','Test']::text[], 0, 'しゅくだい (宿題) = homework.', 30),
  ('n4-easy-02', 'N4', 'easy', 'Grammar', 'The て-form of かく (to write) is:', null, array['かいて','かって','かきて','かいで']::text[], 0, '〜く verbs change to 〜いて: かく → かいて.', 31),
  ('n4-easy-03', 'N4', 'easy', 'Kanji', 'How is 「会社」 read?', null, array['かいしゃ','がっこう','しゃかい','かいぎ']::text[], 0, '会社 = かいしゃ (company). 社会 = しゃかい (society).', 32),
  ('n4-easy-04', 'N4', 'easy', 'Vocabulary', '「やくそく」 means:', null, array['Promise / appointment','Medicine','Station','Weather']::text[], 0, 'やくそく (約束) = a promise or appointment.', 33),
  ('n4-easy-05', 'N4', 'easy', 'Grammar', 'まどを あけて ___。 (Please open the window.)', null, array['ください','ます','です','ました']::text[], 0, '〜てください = please do …', 34),
  ('n4-easy-06', 'N4', 'easy', 'Listening', 'Listen and choose the meaning.', 'あしたは あめが ふるでしょう', array['It rained yesterday','It will probably rain tomorrow','It is sunny today','It is snowing now']::text[], 1, 'ふるでしょう = will probably fall.', 35),
  ('n4-easy-07', 'N4', 'easy', 'Kanji', '「肉」 means:', null, array['Fish','Meat','Vegetables','Rice']::text[], 1, '肉 (にく) = meat. 魚 (さかな) = fish.', 36),
  ('n4-easy-08', 'N4', 'easy', 'Vocabulary', '「いそがしい」 means:', null, array['Busy','Boring','Easy','Kind']::text[], 0, 'いそがしい (忙しい) = busy.', 37),
  ('n4-easy-09', 'N4', 'easy', 'Grammar', 'The potential form of たべる (can eat) is:', null, array['たべられる','たべさせる','たべたい','たべよう']::text[], 0, 'る-verbs: drop る, add られる.', 38),
  ('n4-easy-10', 'N4', 'easy', 'Reading', '「ここで たばこを すわないで ください。」 What does this sign say?', null, array['Please smoke here','Please don''t smoke here','The smoking area is outside','You may smoke']::text[], 1, '〜ないでください = please don''t …', 39),
  ('n4-medium-01', 'N4', 'medium', 'Grammar', '日本語が 少し 話せる ___ なりました。', null, array['ように','ために','ことに','そうに']::text[], 0, '〜ようになる = come to be able to …', 40),
  ('n4-medium-02', 'N4', 'medium', 'Grammar', '空が 暗いですね。雨が 降り ___ です。', null, array['そう','よう','らしい','みたい']::text[], 0, 'Verb stem + そうだ = looks like it''s about to …', 41),
  ('n4-medium-03', 'N4', 'medium', 'Grammar', 'I borrowed a book from a friend: 友だちに 本を ___ました。', null, array['かり','かし','あげ','くれ']::text[], 0, 'かりる = borrow; かす = lend.', 42),
  ('n4-medium-04', 'N4', 'medium', 'Kanji', 'How is 「料理」 read?', null, array['りょうり','りょこう','りょうきん','りゆう']::text[], 0, '料理 = りょうり (cooking). 旅行 = りょこう (travel).', 43),
  ('n4-medium-05', 'N4', 'medium', 'Vocabulary', '「けいけん」 means:', null, array['Experience','Economy','Police','Plan']::text[], 0, 'けいけん (経験) = experience.', 44),
  ('n4-medium-06', 'N4', 'medium', 'Grammar', '日本へ 行った ___ が あります。', null, array['こと','もの','ところ','ほう']::text[], 0, '〜たことがある = have done … before.', 45),
  ('n4-medium-07', 'N4', 'medium', 'Reading', '「昨日は 頭が 痛かったので、学校を 休みました。」 Why was the writer absent?', null, array['They had a headache','They were busy','They overslept','They went on a trip']::text[], 0, '頭が痛かった = had a headache. ので = because.', 46),
  ('n4-medium-08', 'N4', 'medium', 'Listening', 'Listen. What is the speaker asking?', 'すみません、もう一度 言って いただけませんか', array['To repeat something','For directions','Forgiveness for being late','The price']::text[], 0, 'もう一度 言って いただけませんか = Could you say that once more?', 47),
  ('n4-medium-09', 'N4', 'medium', 'Grammar', 'ドアが ___ います。 (The door is open.)', null, array['あいて','あけて','あく','あけ']::text[], 0, 'Intransitive あく + ている describes a state: the door is open.', 48),
  ('n4-medium-10', 'N4', 'medium', 'Kanji', '「急行」 on a train timetable means:', null, array['Express train','Local train','Airport','Hurry up']::text[], 0, '急行 (きゅうこう) = express. 各駅停車 = local (stops at every station).', 49),
  ('n4-hard-01', 'N4', 'hard', 'Grammar', '母に 部屋を そうじ ___ました。 (I was made to clean.)', null, array['させられ','され','させ','して']::text[], 0, 'Causative-passive 〜させられる = be made to do.', 50),
  ('n4-hard-02', 'N4', 'hard', 'Grammar', '明日は 早く 起き ___ なりません。', null, array['なければ','たら','ても','れば']::text[], 0, '〜なければならない = must.', 51),
  ('n4-hard-03', 'N4', 'hard', 'Grammar', '先生が 教室に ___。 (honorific)', null, array['いらっしゃいました','まいりました','おりました','いたしました']::text[], 0, 'いらっしゃる is the respectful form of いる/来る. まいる and おる are humble.', 52),
  ('n4-hard-04', 'N4', 'hard', 'Grammar', 'Humble: 私が 先生の かばんを お持ち ___。', null, array['します','になります','なさいます','くださいます']::text[], 0, 'お + stem + する is humble (my action). お〜になる is respectful.', 53),
  ('n4-hard-05', 'N4', 'hard', 'Kanji', 'How is 「説明」 read?', null, array['せつめい','せいめい','せつめん','ぜつめい']::text[], 0, '説明 = せつめい (explanation).', 54),
  ('n4-hard-06', 'N4', 'hard', 'Vocabulary', '「ようやく」 is closest to:', null, array['Finally / at last','Suddenly','Never','Always']::text[], 0, 'ようやく = finally, after a long time.', 55),
  ('n4-hard-07', 'N4', 'hard', 'Reading', '「この 薬は 食後に 飲んで ください。1日 3回です。」 How should you take it?', null, array['Before meals, 3 times a day','After meals, 3 times a day','Once a day after dinner','Only when you feel sick']::text[], 1, '食後 = after meals; 1日3回 = three times a day.', 56),
  ('n4-hard-08', 'N4', 'hard', 'Listening', 'Listen. What changed?', '会議は 3時から 4時に 変更に なりました', array['The meeting was cancelled','The meeting moved from 3 to 4 o''clock','The meeting lasts 3–4 hours','The meeting starts at 3']::text[], 1, '3時から4時に変更 = changed from 3 to 4 o''clock.', 57),
  ('n4-hard-09', 'N4', 'hard', 'Grammar', '窓を 開けた ___ 寝て しまった。 (left it open)', null, array['まま','ながら','あいだ','うちに']::text[], 0, '〜たまま = with … still in that state.', 58),
  ('n4-hard-10', 'N4', 'hard', 'Vocabulary', '「かならず」 means:', null, array['Without fail','Maybe','Sometimes','Rarely']::text[], 0, 'かならず (必ず) = surely, without fail.', 59),
  ('n3-easy-01', 'N3', 'easy', 'Vocabulary', '「締め切り」 means:', null, array['Deadline','Holiday','Contract','Salary']::text[], 0, '締め切り (しめきり) = deadline.', 60),
  ('n3-easy-02', 'N3', 'easy', 'Grammar', '雨が 降った ___、試合は 中止に なった。', null, array['せいで','おかげで','くせに','わりに']::text[], 0, 'せいで = because of (a negative result). おかげで is for positive results.', 61),
  ('n3-easy-03', 'N3', 'easy', 'Kanji', 'How is 「経験」 read?', null, array['けいけん','きょうけん','けいげん','けいかん']::text[], 0, '経験 = けいけん (experience).', 62),
  ('n3-easy-04', 'N3', 'easy', 'Vocabulary', '「あきらめる」 means:', null, array['To give up','To remember','To decide','To hurry']::text[], 0, 'あきらめる (諦める) = to give up.', 63),
  ('n3-easy-05', 'N3', 'easy', 'Grammar', '日本に 来て ___、毎日 日本語を 使っています。', null, array['以来','ばかり','ところ','うちに']::text[], 0, '〜て以来 = ever since …', 64),
  ('n3-easy-06', 'N3', 'easy', 'Listening', 'Listen. What is the restaurant saying?', '申し訳ございません、ただいま 満席です', array['Sorry, we''re full right now','We''re closed today','Please wait outside','Your table is ready']::text[], 0, '満席 (まんせき) = all seats taken.', 65),
  ('n3-easy-07', 'N3', 'easy', 'Kanji', '「募集」 on a poster means:', null, array['Recruiting / wanted','Resignation','Holiday','Promotion']::text[], 0, '募集 (ぼしゅう) = recruitment, as in アルバイト募集.', 66),
  ('n3-easy-08', 'N3', 'easy', 'Grammar', '忙しい ___、手伝って くれて ありがとう。', null, array['のに','ので','から','ため']::text[], 0, 'のに = even though: “Thanks for helping even though you''re busy.”', 67),
  ('n3-easy-09', 'N3', 'easy', 'Vocabulary', '「ぎりぎり」 means:', null, array['Just barely / at the last moment','Very slowly','Completely','Quietly']::text[], 0, 'ぎりぎり間に合った = made it just in time.', 68),
  ('n3-easy-10', 'N3', 'easy', 'Reading', '「本日は 定休日の ため、営業して おりません。」 What does this notice say?', null, array['Open today','Closed today — regular holiday','Closing early','Under renovation']::text[], 1, '定休日 = regular closing day.', 69),
  ('n3-medium-01', 'N3', 'medium', 'Grammar', 'この 本は 読めば 読む ___ おもしろく なる。', null, array['ほど','だけ','ばかり','まで']::text[], 0, '〜ば〜ほど = the more …, the more …', 70),
  ('n3-medium-02', 'N3', 'medium', 'Grammar', '彼は 知っている ___、何も 言わなかった。', null, array['くせに','おかげで','ために','ように']::text[], 0, 'くせに = even though (with criticism).', 71),
  ('n3-medium-03', 'N3', 'medium', 'Grammar', '日本語が 上手に なる ___、毎日 練習して います。', null, array['ように','ために','ことに','までに']::text[], 0, 'なる is non-volitional, so use ように (so that). ために needs a volitional verb.', 72),
  ('n3-medium-04', 'N3', 'medium', 'Kanji', 'How is 「営業」 read?', null, array['えいぎょう','えいごう','けいぎょう','えいぎょ']::text[], 0, '営業 = えいぎょう (business, sales).', 73),
  ('n3-medium-05', 'N3', 'medium', 'Vocabulary', '「延期」 means:', null, array['Postponement','Cancellation','Early start','Rehearsal']::text[], 0, '延期 (えんき) = postponement.', 74),
  ('n3-medium-06', 'N3', 'medium', 'Reading', '「参加を ご希望の 方は、今月 20日までに メールで お申し込み ください。」 What should you do?', null, array['Apply by email by the 20th','Apply in person on the 20th','Just come on the 20th','No application needed']::text[], 0, '20日までに = by the 20th; メールで = by email.', 75),
  ('n3-medium-07', 'N3', 'medium', 'Listening', 'Listen. What is the speaker saying?', '電車が 遅れて いる ので、少し 遅く なります', array['I''ll be a little late — the train is delayed','The train was cancelled','I''m already at the station','I''ll arrive early']::text[], 0, '電車が遅れている = the train is running late.', 76),
  ('n3-medium-08', 'N3', 'medium', 'Grammar', '彼の 話に よると、明日は 休み ___。', null, array['だそうです','らしくない','ようにする','べきです']::text[], 0, '〜によると…そうです = according to …, I hear that …', 77),
  ('n3-medium-09', 'N3', 'medium', 'Vocabulary', '「思わず」 means:', null, array['Without thinking','Certainly','Deliberately','Regularly']::text[], 0, '思わず笑った = laughed in spite of myself.', 78),
  ('n3-medium-10', 'N3', 'medium', 'Kanji', 'How is 「確認」 read?', null, array['かくにん','かくにち','かくじん','がくにん']::text[], 0, '確認 = かくにん (confirmation).', 79),
  ('n3-hard-01', 'N3', 'hard', 'Grammar', '忙しい ___、彼は 毎日 ジムに 通って いる。', null, array['にもかかわらず','によって','に対して','にとって']::text[], 0, 'にもかかわらず = despite.', 80),
  ('n3-hard-02', 'N3', 'hard', 'Grammar', '子ども ___、この 問題は 難しすぎる。', null, array['にとって','について','によって','に対して']::text[], 0, 'にとって = for, from the point of view of.', 81),
  ('n3-hard-03', 'N3', 'hard', 'Grammar', '彼女は 今にも 泣き ___ 顔を して いた。', null, array['そうな','ような','らしい','みたいな']::text[], 0, '今にも + stem + そうな = looking as if about to …', 82),
  ('n3-hard-04', 'N3', 'hard', 'Grammar', '彼の 意見に ___、私は 反対です。', null, array['対して','よって','とって','ついて']::text[], 0, '〜に対して = towards, against.', 83),
  ('n3-hard-05', 'N3', 'hard', 'Kanji', 'How is 「規則」 read?', null, array['きそく','きぞく','きそ','ぎそく']::text[], 0, '規則 = きそく (rule). 貴族 = きぞく (nobility).', 84),
  ('n3-hard-06', 'N3', 'hard', 'Vocabulary', '「さっぱり わからない」 means:', null, array['Don''t understand at all','Understand a little','Understand perfectly','Almost understand']::text[], 0, 'さっぱり + negative = not at all.', 85),
  ('n3-hard-07', 'N3', 'hard', 'Reading', '「当店では、お客様の 安全の ため、店内での 撮影を ご遠慮 いただいて おります。」 What is the rule?', null, array['Please don''t take photos inside','Photos are welcome','Safety equipment is required','The store is closed for safety']::text[], 0, '撮影をご遠慮ください = please refrain from taking photos.', 86),
  ('n3-hard-08', 'N3', 'hard', 'Listening', 'Listen. What will the company do?', 'この 件に ついては、後ほど 改めて ご連絡 いたします', array['Contact you again later about this','Close the matter','Ask you to call now','Nothing — they already contacted you']::text[], 0, '後ほど改めてご連絡いたします = we will contact you again later.', 87),
  ('n3-hard-09', 'N3', 'hard', 'Vocabulary', '「油断」 means:', null, array['Carelessness','Oil price','Decision','Patience']::text[], 0, '油断 (ゆだん) = letting your guard down. 油断大敵 = carelessness is the greatest enemy.', 88),
  ('n3-hard-10', 'N3', 'hard', 'Kanji', '「貯金」 means:', null, array['Savings','Loan','Salary','Tax']::text[], 0, '貯金 (ちょきん) = savings.', 89),
  ('n2-easy-01', 'N2', 'easy', 'Vocabulary', '「把握」 means:', null, array['Grasp / understand','Delay','Estimate','Refuse']::text[], 0, '把握 (はあく) = grasp, as in 状況を把握する.', 90),
  ('n2-easy-02', 'N2', 'easy', 'Grammar', '彼の 努力 ___、プロジェクトは 成功した。', null, array['のおかげで','のせいで','のくせに','のわりに']::text[], 0, 'おかげで = thanks to (a positive result).', 91),
  ('n2-easy-03', 'N2', 'easy', 'Kanji', 'How is 「傾向」 read?', null, array['けいこう','けいきょう','けいこ','きょうこう']::text[], 0, '傾向 = けいこう (tendency).', 92),
  ('n2-easy-04', 'N2', 'easy', 'Grammar', '学生 ___、よく 勉強しなさい。', null, array['である以上','であるにしても','であるものの','であるくせに']::text[], 0, '〜以上 = since / as long as (you are …).', 93),
  ('n2-easy-05', 'N2', 'easy', 'Vocabulary', '「妥協」 means:', null, array['Compromise','Victory','Refusal','Promotion']::text[], 0, '妥協 (だきょう) = compromise.', 94),
  ('n2-easy-06', 'N2', 'easy', 'Listening', 'Listen. What is being asked?', '恐れ入りますが、少々 お待ち いただけますか', array['Could you please wait a moment?','We''re closed, sorry','Please come back tomorrow','Sorry for the wait']::text[], 0, '少々お待ちいただけますか = could you wait a moment?', 95),
  ('n2-easy-07', 'N2', 'easy', 'Grammar', '雨が 降る ___ 降らない ___、イベントは 行います。', null, array['にしろ / にしろ','から / から','ので / ので','のに / のに']::text[], 0, 'AにしろBにしろ = whether A or B.', 96),
  ('n2-easy-08', 'N2', 'easy', 'Kanji', 'How is 「著しい」 read?', null, array['いちじるしい','いちじるい','ちょしい','あらわしい']::text[], 0, '著しい = いちじるしい (remarkable).', 97),
  ('n2-easy-09', 'N2', 'easy', 'Vocabulary', '「いきなり」 means:', null, array['Suddenly','Gradually','Carefully','Eventually']::text[], 0, 'いきなり = suddenly, without warning.', 98),
  ('n2-easy-10', 'N2', 'easy', 'Reading', '「本製品は、高温多湿を 避けて 保管して ください。」 How should it be stored?', null, array['Away from heat and humidity','In a warm place','In the fridge','Use within a day']::text[], 0, '高温多湿を避けて = avoiding high temperature and humidity.', 99),
  ('n2-medium-01', 'N2', 'medium', 'Grammar', '彼は 医者 ___、患者の 気持ちが わからない。', null, array['のくせに','のおかげで','にとって','について']::text[], 0, 'のくせに = even though he is (critical).', 100),
  ('n2-medium-02', 'N2', 'medium', 'Grammar', 'この 仕事は 経験が ない 人 ___ 無理だ。', null, array['には','では','にも','とは']::text[], 0, '〜には無理だ = impossible for …', 101),
  ('n2-medium-03', 'N2', 'medium', 'Grammar', '年を とる ___、体力が 落ちて くる。', null, array['につれて','によって','にとって','に対して']::text[], 0, 'につれて = as … goes on.', 102),
  ('n2-medium-04', 'N2', 'medium', 'Kanji', 'How is 「矛盾」 read?', null, array['むじゅん','ほこじゅん','むしゅん','ぼうじゅん']::text[], 0, '矛盾 = むじゅん (contradiction).', 103),
  ('n2-medium-05', 'N2', 'medium', 'Vocabulary', '「おおざっぱ」 means:', null, array['Rough, not detailed','Very generous','Extremely careful','Quiet']::text[], 0, 'おおざっぱ (大雑把) = rough, broad-brush.', 104),
  ('n2-medium-06', 'N2', 'medium', 'Reading', '「新製品の 発売は、部品の 供給が 遅れて いる ため、来月に 延期されました。」 What happened?', null, array['Launch postponed to next month — parts delay','Launched early due to demand','Product cancelled','Price increased']::text[], 0, '供給が遅れている = supply is delayed; 延期 = postponed.', 105),
  ('n2-medium-07', 'N2', 'medium', 'Listening', 'Listen. What should you do?', 'お手数ですが、こちらの 書類に ご記入 ください', array['Fill in this form','Nothing — the form is done','Sign later','Bring documents next time']::text[], 0, '書類にご記入ください = please fill in the form.', 106),
  ('n2-medium-08', 'N2', 'medium', 'Grammar', 'いくら 頼まれ ___、その 仕事は 引き受けられない。', null, array['ても','たら','ば','なら']::text[], 0, 'いくら〜ても = no matter how much …', 107),
  ('n2-medium-09', 'N2', 'medium', 'Vocabulary', '「見直す」 means:', null, array['To review / reconsider','To look down on','To overlook','To look forward to']::text[], 0, '見直す = look at again, reconsider (also: think better of).', 108),
  ('n2-medium-10', 'N2', 'medium', 'Kanji', 'How is 「携帯」 read?', null, array['けいたい','けいだい','きょうたい','けたい']::text[], 0, '携帯 = けいたい, as in 携帯電話 (mobile phone).', 109),
  ('n2-hard-01', 'N2', 'hard', 'Grammar', '彼の 実力 ___、優勝は 間違いない。', null, array['からすれば','にかけては','に反して','をめぐって']::text[], 0, 'からすれば = judging from.', 110),
  ('n2-hard-02', 'N2', 'hard', 'Grammar', '予想 ___、試験は とても 簡単だった。', null, array['に反して','に沿って','に基づいて','に応じて']::text[], 0, 'に反して = contrary to.', 111),
  ('n2-hard-03', 'N2', 'hard', 'Grammar', 'この 問題 ___、会議で 激しい 議論が あった。', null, array['をめぐって','に際して','にわたって','につき']::text[], 0, 'をめぐって = over, concerning (a dispute).', 112),
  ('n2-hard-04', 'N2', 'hard', 'Grammar', '3日間 ___、会議が 行われた。', null, array['にわたって','をめぐって','に反して','に沿って']::text[], 0, 'にわたって = over a span of (time/space).', 113),
  ('n2-hard-05', 'N2', 'hard', 'Kanji', 'How is 「潔い」 read?', null, array['いさぎよい','きよい','けがらわしい','こころよい']::text[], 0, '潔い = いさぎよい (graceful, manly in accepting).', 114),
  ('n2-hard-06', 'N2', 'hard', 'Vocabulary', '「ひたすら」 means:', null, array['Single-mindedly','Occasionally','Reluctantly','Casually']::text[], 0, 'ひたすら = earnestly, with total focus.', 115),
  ('n2-hard-07', 'N2', 'hard', 'Reading', '「弊社は、お客様の 個人情報を 法令に 基づき 適切に 管理いたします。」 What does the company promise?', null, array['To manage personal data properly under the law','To sell personal data','Not to collect personal data','To delete it every day']::text[], 0, '法令に基づき = in accordance with laws; 適切に管理 = manage properly.', 116),
  ('n2-hard-08', 'N2', 'hard', 'Listening', 'Listen. What is the speaker saying?', 'ご期待に 添えず、誠に 申し訳ございません', array['We''re very sorry we couldn''t meet your expectations','Thank you for your expectations','We exceeded expectations','Please wait for our reply']::text[], 0, 'ご期待に添えず = failing to meet your expectations.', 117),
  ('n2-hard-09', 'N2', 'hard', 'Vocabulary', '「根回し」 in business means:', null, array['Building consensus behind the scenes','Gardening','The final decision','A public announcement']::text[], 0, '根回し (ねまわし) = laying the groundwork before a formal decision.', 118),
  ('n2-hard-10', 'N2', 'hard', 'Kanji', 'How is 「漸く」 read?', null, array['ようやく','しばらく','ぜんく','すばやく']::text[], 0, '漸く = ようやく (finally).', 119),
  ('n1-easy-01', 'N1', 'easy', 'Vocabulary', '「懸念」 means:', null, array['Concern / worry','Celebration','Contract','Achievement']::text[], 0, '懸念 (けねん) = concern.', 120),
  ('n1-easy-02', 'N1', 'easy', 'Grammar', '彼は 挨拶 ___、黙って 帰って しまった。', null, array['もせずに','もしながら','をしつつ','ばかりに']::text[], 0, '〜もせずに = without even doing …', 121),
  ('n1-easy-03', 'N1', 'easy', 'Kanji', 'How is 「曖昧」 read?', null, array['あいまい','あいまつ','えいまい','あいみ']::text[], 0, '曖昧 = あいまい (vague).', 122),
  ('n1-easy-04', 'N1', 'easy', 'Vocabulary', '「おろそか」 means:', null, array['Neglectful','Careful','Generous','Fast']::text[], 0, 'おろそかにする = neglect.', 123),
  ('n1-easy-05', 'N1', 'easy', 'Grammar', '社長 ___、社員全員が 反対した。', null, array['をはじめ','をもって','をよそに','をおいて']::text[], 0, 'をはじめ = starting with, including.', 124),
  ('n1-easy-06', 'N1', 'easy', 'Listening', 'Listen. What is being requested?', 'つきましては、ご出席の ほど よろしく お願い 申し上げます', array['Your attendance, kindly','Sorry — it''s cancelled','Reply by email','Attendance is optional']::text[], 0, 'ご出席のほどよろしくお願い申し上げます = we kindly request your attendance.', 125),
  ('n1-easy-07', 'N1', 'easy', 'Kanji', 'How is 「顕著」 read?', null, array['けんちょ','けんしょ','けんじょ','げんちょ']::text[], 0, '顕著 = けんちょ (remarkable, notable).', 126),
  ('n1-easy-08', 'N1', 'easy', 'Grammar', '彼の 助け ___、この 成功は なかった だろう。', null, array['なくしては','をよそに','ともなると','にかこつけて']::text[], 0, '〜なくしては = without …', 127),
  ('n1-easy-09', 'N1', 'easy', 'Vocabulary', '「目処が 立つ」 means:', null, array['To have an outlook in sight','To stand up','To lose hope','To look away']::text[], 0, '目処 (めど) が立つ = a prospect of completion is in sight.', 128),
  ('n1-easy-10', 'N1', 'easy', 'Reading', '「本件に 関しては、関係各所と 協議の 上、追って ご報告 いたします。」 What will happen?', null, array['A report later, after consulting the relevant parties','It has already been reported','It has been cancelled','No report is needed']::text[], 0, '協議の上 = after discussion; 追って = later.', 129),
  ('n1-medium-01', 'N1', 'medium', 'Grammar', '親の 心配 ___、彼は 危険な 旅に 出た。', null, array['をよそに','をもって','をおいて','を皮切りに']::text[], 0, 'をよそに = ignoring, in disregard of.', 130),
  ('n1-medium-02', 'N1', 'medium', 'Grammar', '東京 ___、全国 各地で コンサートが 開かれる。', null, array['を皮切りに','をよそに','をもって','にひきかえ']::text[], 0, 'を皮切りに = starting with.', 131),
  ('n1-medium-03', 'N1', 'medium', 'Grammar', '兄 ___、弟は とても 真面目だ。', null, array['にひきかえ','をよそに','を皮切りに','をおいて']::text[], 0, 'にひきかえ = in contrast to.', 132),
  ('n1-medium-04', 'N1', 'medium', 'Kanji', 'How is 「覆す」 read?', null, array['くつがえす','おおす','ふくがえす','ひるがえす']::text[], 0, '覆す = くつがえす (overturn).', 133),
  ('n1-medium-05', 'N1', 'medium', 'Vocabulary', '「しがらみ」 means:', null, array['Ties and obligations that bind you','Sudden luck','Deep regret','Silent anger']::text[], 0, 'しがらみ = binding social ties.', 134),
  ('n1-medium-06', 'N1', 'medium', 'Reading', '「当該 規約に 違反した 場合、事前の 通知 なく アカウントを 停止する ことが あります。」 What can happen?', null, array['Suspension without prior notice for violations','A one-week notice first','Only a warning','Deletion after a month']::text[], 0, '事前の通知なく = without prior notice.', 135),
  ('n1-medium-07', 'N1', 'medium', 'Listening', 'Listen. What is the shop announcing?', '誠に 勝手ながら、本日を もちまして 閉店 させて いただきます', array['It is closing permanently as of today','It is opening today','It is closed only today','It is moving tomorrow']::text[], 0, '本日をもちまして閉店 = closing as of today.', 136),
  ('n1-medium-08', 'N1', 'medium', 'Grammar', '彼の 実力 ___、この 試験に 落ちる はずが ない。', null, array['をもってすれば','をよそに','にひきかえ','を皮切りに']::text[], 0, 'をもってすれば = with (that ability).', 137),
  ('n1-medium-09', 'N1', 'medium', 'Vocabulary', '「いたたまれない」 means:', null, array['Unbearable, can''t stay put','Very comfortable','Impossible to hear','Unforgettable']::text[], 0, 'いたたまれない = so uncomfortable you can''t stay.', 138),
  ('n1-medium-10', 'N1', 'medium', 'Kanji', 'How is 「懐柔」 read?', null, array['かいじゅう','ふところじゅう','かいにゅう','えいじゅう']::text[], 0, '懐柔 = かいじゅう (winning over).', 139),
  ('n1-hard-01', 'N1', 'hard', 'Grammar', '彼は 優秀な 研究者で ある ___、優れた 教育者でも ある。', null, array['と同時に','にもまして','をおいて','といえども']::text[], 0, 'と同時に = at the same time, as well as.', 140),
  ('n1-hard-02', 'N1', 'hard', 'Grammar', '子ども ___、そんな 言い訳は 通用しない。', null, array['といえども','をおいて','ともなると','ならでは']::text[], 0, 'といえども = even if (someone is) …', 141),
  ('n1-hard-03', 'N1', 'hard', 'Grammar', 'この 仕事を 任せられるのは、彼 ___ ほかに いない。', null, array['をおいて','をよそに','ならでは','といえども']::text[], 0, 'をおいてほかにない = no one other than.', 142),
  ('n1-hard-04', 'N1', 'hard', 'Grammar', '京都 ___ の 美しい 景色。', null, array['ならでは','をおいて','ともなると','といえども']::text[], 0, 'ならでは = unique to.', 143),
  ('n1-hard-05', 'N1', 'hard', 'Kanji', 'How is 「遡る」 read?', null, array['さかのぼる','そうる','さからう','のぼる']::text[], 0, '遡る = さかのぼる (go back, trace back).', 144),
  ('n1-hard-06', 'N1', 'hard', 'Vocabulary', '「おこがましい」 means:', null, array['Presumptuous','Humble','Delicious','Nostalgic']::text[], 0, 'おこがましい = presumptuous, impertinent.', 145),
  ('n1-hard-07', 'N1', 'hard', 'Reading', '「前述の 通り、本研究の 結果は 限定的な 条件下で 得られた もので あり、一般化には 慎重を 期す 必要が ある。」 What is the point?', null, array['Results came from limited conditions — generalise with care','Results apply everywhere','The research was cancelled','Conditions were unlimited']::text[], 0, '一般化には慎重を期す = be cautious about generalising.', 146),
  ('n1-hard-08', 'N1', 'hard', 'Listening', 'Listen. What is the speaker''s position?', 'お言葉を 返す ようですが、その 案には 賛成 しかねます', array['Sorry to contradict, but I can''t agree with that plan','I fully agree','Please repeat that','I''ll think about it later']::text[], 0, '賛成しかねます = I''m unable to agree (polite refusal).', 147),
  ('n1-hard-09', 'N1', 'hard', 'Vocabulary', '「やぶさかでない」 means:', null, array['Willing, not reluctant','Unwilling','Impossible','Forbidden']::text[], 0, '〜にやぶさかでない = willing to …', 148),
  ('n1-hard-10', 'N1', 'hard', 'Kanji', 'How is 「杜撰」 read?', null, array['ずさん','とせん','もりせん','ずせん']::text[], 0, '杜撰 = ずさん (sloppy).', 149)
